<?php $pageTitle='Enrollments';$active='enrollments';require_once __DIR__.'/../includes/auth.php';require_role('admin');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'')==='add'){$sid=(int)$_POST['student_id'];$cid=(int)$_POST['course_id'];$pdo->prepare('INSERT IGNORE INTO enrollments(student_id,course_id) VALUES(?,?)')->execute([$sid,$cid]);flash('success','Enrollment added.');}elseif(($_POST['action']??'')==='delete'){$pdo->prepare('DELETE FROM enrollments WHERE id=?')->execute([(int)$_POST['enrollment_id']]);flash('success','Enrollment removed.');}redirect('enrollments.php');}catch(Throwable $e){$error=$e->getMessage();}}$students=$pdo->query("SELECT id,full_name,enrollment_no FROM users WHERE role='student' AND status='active' ORDER BY full_name")->fetchAll();$courses=$pdo->query("SELECT id,title FROM courses WHERE status='published' ORDER BY title")->fetchAll();$rows=$pdo->query("SELECT e.*,u.full_name student,u.enrollment_no,c.title course_title,t.full_name teacher FROM enrollments e JOIN users u ON u.id=e.student_id JOIN courses c ON c.id=e.course_id JOIN users t ON t.id=c.teacher_id ORDER BY e.enrolled_at DESC")->fetchAll();require_once __DIR__.'/../includes/app_start.php';?>
<div class="page-header"><div><div class="section-kicker mb-2">Enrollment management</div><h1>Enrollments</h1><p>Track and manually manage course enrollment.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><h4>Add Enrollment</h4><form method="post" class="row g-3 mt-1"><?=csrf_input()?><input type="hidden" name="action" value="add"><div class="col-md-5"><label class="form-label">Student</label><select name="student_id" class="form-select" required><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['full_name'])?><?= $s['enrollment_no']?' · '.e($s['enrollment_no']):'' ?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label">Course</label><select name="course_id" class="form-select" required><?php foreach($courses as $c):?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Enroll</button></div></form></div><div class="card p-0 overflow-hidden"><div class="table-responsive border-0"><table class="table"><thead><tr><th class="ps-4">Student</th><th>Course</th><th>Teacher</th><th>Enrolled</th><th>Progress</th><th class="pe-4">Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="ps-4"><div class="fw-semibold"><?=e($r['student'])?></div><div class="small text-muted"><?=e($r['enrollment_no']??'')?></div></td><td><?=e($r['course_title'])?></td><td><?=e($r['teacher'])?></td><td><?=e(date('d M Y',strtotime($r['enrolled_at'])))?></td><td style="min-width:150px"><div class="d-flex justify-content-between small"><span><?=e($r['progress_percent'])?>%</span></div><div class="progress"><div class="progress-bar" style="width:<?=min(100,(float)$r['progress_percent'])?>%"></div></div></td><td class="pe-4"><form method="post" data-confirm="Remove this enrollment?"><?=csrf_input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="enrollment_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../includes/app_end.php'; ?>
